        {
            switch (action)
            {
                case ACTION_MOVE_CENTR_POSS:
                    EventProgress = true;
                    me->SetHomePosition(CentrPos[0]);
                    me->GetMotionMaster()->MovePoint(1, CentrPos[0]);
                    break;
            }
        }

        void DamageTakenAfterScaling(Unit* who, uint32& damage, DamageEffectType dmgType)
        {
            Player* looter = who ? who->GetAffectingPlayer() : nullptr;
            if (!looter)
            {
                if (damage >= me->GetHealth(who))
                    damage = 0;
                return;
            }

            if (damage >= me->GetHealth(who))
            {
                damage = 0;

                if (EventProgress)
                {
                    EventProgress = false;
                    QuestCredit();
                    me->setFaction(35);
                    me->RemoveAllAuras();
                    me->GeneratePersonalLoot(me, looter);
                    Talk(SAY_YULON_END);
                    if (auto Shao = me->GetAnyOwner())
                        Shao->GetAI()->DoAction(ACTION_YULON_END);
                }
                EnterEvadeMode();
            }
        }

